/* Regenerates js/data/operators.js, js/data/framework.js and js/data/logos.js from the
   Operator Profile Explorer export (live revenuenomad.com data).
   usage: node tools/build-data.js <path-to-explorer-index.html> */
const fs = require('fs');
const path = require('path');
const src = process.argv[2];
if (!src) { console.error('usage: node tools/build-data.js <explorer index.html>'); process.exit(1); }
const s = fs.readFileSync(src, 'utf8');
const ops = JSON.parse(s.match(/const RN_OPS = (\[.*?\]);\s*\n/s)[1]);
const data = JSON.parse(s.match(/const DATA = (\{.*?\});\s*\n/s)[1]);
const logos = JSON.parse(s.match(/const LOGOS = (\{.*?\});\s*\n/s)[1]);
for (const o of ops) if (o.photo) o.photo = 'assets/' + o.photo; // photos/<id>.jpg -> assets/photos/<id>.jpg
const out = path.join(__dirname, '..', 'js', 'data');
const head = '/* Generated by tools/build-data.js from the live-data export. Do not edit by hand. */\n';
fs.writeFileSync(path.join(out, 'operators.js'), head + 'window.RN = window.RN || {}; RN.data = RN.data || {};\nRN.data.rawOps = ' + JSON.stringify(ops) + ';\n');
fs.writeFileSync(path.join(out, 'framework.js'), head + 'window.RN = window.RN || {}; RN.data = RN.data || {};\nRN.data.framework = ' + JSON.stringify(data) + ';\n');
fs.writeFileSync(path.join(out, 'logos.js'), head + 'window.RN = window.RN || {}; RN.data = RN.data || {};\nRN.data.logos = ' + JSON.stringify(logos) + ';\n');
console.log('operators', ops.length, 'logos', Object.keys(logos).length, Object.keys(logos));
